<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.405" />
  </ItemGroup>
</Project>
EOF

cat > /tmp/parse_binlog.cs << 'CSEOF'
using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

        // Collect all errors and warnings
        var errors = new List<(string Project, string Code, string File, int Line, string Message)>();
        var warnings = new List<(string Project, string Code, string File, int Line, string Message)>();
        var projectResults = new Dictionary<string, bool>();

        build.VisitAllChildren<BaseNode>(node =>
        {
            if (node is Microsoft.Build.Logging.StructuredLogger.Error err)
            {
                var proj = FindParentProject(err);
                errors.Add((proj, err.Code ?? "", err.File ?? "", err.LineNumber, err.Text ?? err.ToString()));
            }
            else if (node is Microsoft.Build.Logging.StructuredLogger.Warning warn)
            {
                warnings.Add((FindParentProject(warn), warn.Code ?? "", warn.File ?? "", warn.LineNumber, warn.Text ?? warn.ToString()));
            }
            else if (node is Project p)
            {
                projectResults[p.Name ?? ""] = p.Succeeded;
            }
        });

        Console.WriteLine("=== FAILED PROJECTS ===");
        foreach (var kv in projectResults.Where(x => !x.Value))
            Console.WriteLine("  FAILED: " + kv.Key);
        Console.WriteLine();

        Console.WriteLine($"=== ERRORS ({errors.Count} total) ===");
        foreach (var e in errors)
        {
            Console.WriteLine($"  [{e.Code}] Project: {e.Project}");
            Console.WriteLine($"    File: {e.File}:{e.Line}");
            Console.WriteLine($"    Message: {e.Message}");
            Console.WriteLine();
        }

        Console.WriteLine($"=== WARNINGS ({warnings.Count} total) ===");
        foreach (var w in warnings)
        {
            Console.WriteLine($"  [{w.Code}] Project: {w.Project}");
            Console.WriteLine($"    File: {w.File}:{w.Line}");
            Console.WriteLine($"    Message: {w.Message}");
            Console.WriteLine();
        }
    }

    static string FindParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "";
            if (current is Target t)
            {
                var pp = t.Parent;
                while (pp != null)
                {
                    if (pp is Project pr) return pr.Name ?? "";
                    pp = (pp as BaseNode)?.Parent;
                }
            }
            current = (current as BaseNode)?.Parent;
        }
        return "<unknown>";
    }
}
