using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

// List all projects
Console.WriteLine("=== ALL PROJECTS ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name} (Target: {p.TargetFramework})");
});

// Find package references and project references from the build
Console.WriteLine("\n=== LOOKING FOR PACKAGE/PROJECT REFS ===");
build.VisitAllChildren<BaseNode>(node => {
    var text = node.ToString();
    if (text != null && (text.Contains("Newtonsoft") || text.Contains("PackageReference")))
    {
        Console.WriteLine($"  [{node.GetType().Name}] {text}");
    }
});

// Look at items added
Console.WriteLine("\n=== ITEMS WITH NEWTONSOFT ===");
build.VisitAllChildren<Item>(item => {
    if (item.ToString()?.Contains("Newtonsoft") == true)
        Console.WriteLine($"  {item}");
});

// Look for AddItem/RemoveItem
Console.WriteLine("\n=== NAMED NODES WITH NEWTONSOFT ===");
build.VisitAllChildren<NamedNode>(n => {
    if (n.Name?.Contains("Newtonsoft") == true || n.ToString()?.Contains("Newtonsoft") == true)
        Console.WriteLine($"  [{n.GetType().Name}] {n.Name}: {n}");
});

// Check for the .csproj content embedded
Console.WriteLine("\n=== MESSAGES ABOUT REFERENCES ===");
build.VisitAllChildren<Message>(m => {
    var t = m.Text ?? "";
    if (t.Contains("Newtonsoft") || t.Contains("PackageReference") || t.Contains("ResolveAssemblyReference") || t.Contains("Services.csproj"))
        Console.WriteLine($"  {t.Substring(0, Math.Min(200, t.Length))}");
});
