// Find all AddItem entries for PackageReference in Services project context
Console.WriteLine("=== PackageReference items per project ===");
build.VisitAllChildren<AddItem>(ai => {
    if (ai.Name == "PackageReference")
    {
        var proj = FindParentProject(ai);
        Console.WriteLine($"  Project: {proj}");
        foreach (var child in ai.Children)
            Console.WriteLine($"    {child}");
    }
});

// Find ProjectReference items
Console.WriteLine("\n=== ProjectReference items per project ===");
build.VisitAllChildren<AddItem>(ai => {
    if (ai.Name == "ProjectReference")
    {
        var proj = FindParentProject(ai);
        Console.WriteLine($"  Project: {proj}");
        foreach (var child in ai.Children)
            Console.WriteLine($"    {child}");
    }
});

// Check for any NuGet restore warnings/errors
Console.WriteLine("\n=== NuGet/Restore messages ===");
build.VisitAllChildren<Message>(m => {
    var t = m.Text ?? "";
    if (t.Contains("NU") || t.Contains("restore") || t.Contains("Restore"))
        if (t.Length < 300)
            Console.WriteLine($"  {t}");
});

// Check which projects failed 
Console.WriteLine("\n=== Project build outcomes ===");
build.VisitAllChildren<Project>(p => {
    // check if the project has errors
    var hasErrors = false;
    p.VisitAllChildren<Microsoft.Build.Logging.StructuredLogger.Error>(e => hasErrors = true);
    if (hasErrors || p.Name == "Api.csproj")
        Console.WriteLine($"  {p.Name} has errors: {hasErrors}");
});

static string FindParentProject(BaseNode node)
{
    var current = node.Parent;
    while (current != null)
    {
        if (current is Project p) return p.Name ?? "";
        current = (current as BaseNode)?.Parent;
    }
    return "<unknown>";
}
